INSERT INTO "job" ("id","level","nameFr","nameEn","payPerShift","energyCost","hungerCost","hygieneCost","shiftGameHours","riskPercent","category","emoji","descFr","descEn","enabled") VALUES ('agent_commercial_yas', 'QUALIFIE', 'Agent commercial Yas', 'Yas sales agent', 6800, 7, 8, 3, 6, 0, 'commerce', '🛍️', 'Vendre forfaits, cartes SIM et téléphones en boutique Yas et prospecter les entreprises. Demande un BT ou plus en commerce ou en télécoms.', 'Sell plans, SIM cards and phones in Yas shops and canvass businesses. Requires a technical diploma or higher in business or telecoms.', true) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "job" ("id","level","nameFr","nameEn","payPerShift","energyCost","hungerCost","hygieneCost","shiftGameHours","riskPercent","category","emoji","descFr","descEn","enabled") VALUES ('charge_communication', 'DIPLOME', 'Chargé de communication', 'Communications officer', 12500, 6, 8, 2, 8, 0, 'media', '📣', 'Rédiger les messages de la marque, animer les réseaux sociaux et préparer les campagnes. Demande une licence en journalisme ou en commerce.', 'Write the brand’s messages, run social media and prepare campaigns. Requires a bachelor’s in journalism or business.', true) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "job" ("id","level","nameFr","nameEn","payPerShift","energyCost","hungerCost","hygieneCost","shiftGameHours","riskPercent","category","emoji","descFr","descEn","enabled") VALUES ('developpeur_mobile', 'DIPLOME', 'Développeur applications mobiles', 'Mobile app developer', 14500, 6, 8, 2, 8, 0, 'numerique', '📱', 'Programmer les applications et services mobiles de l’opérateur (paiement, forfaits, assistance). Demande une licence en informatique.', 'Program the operator’s mobile apps and services (payment, plans, support). Requires a computing bachelor’s.', true) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "job" ("id","level","nameFr","nameEn","payPerShift","energyCost","hungerCost","hygieneCost","shiftGameHours","riskPercent","category","emoji","descFr","descEn","enabled") VALUES ('chef_projet_telecom', 'DIPLOME', 'Chef de projet télécoms', 'Telecom project manager', 25000, 7, 8, 2, 8, 0, 'telecom', '🗼', 'Piloter le déploiement d’antennes, de fibre et de services réseau. Demande un master en télécoms ou en informatique.', 'Lead the roll-out of antennas, fibre and network services. Requires a master’s in telecoms or computing.', true) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "job" ("id","level","nameFr","nameEn","payPerShift","energyCost","hungerCost","hygieneCost","shiftGameHours","riskPercent","category","emoji","descFr","descEn","enabled") VALUES ('directeur_communication', 'DIPLOME', 'Directeur de la communication', 'Communications director', 22000, 6, 8, 2, 8, 0, 'media', '📢', 'Définir l’image de la marque, les campagnes et les relations avec la presse. Demande un master en journalisme ou en commerce.', 'Set the brand image, campaigns and press relations. Requires a master’s in journalism or business.', true) ON CONFLICT ("id") DO NOTHING;
